function renderClothing(){let cat=window.activeCategory||'Shoes';return `${panelHead('clothing','Wardrobe','Choose individual pieces. Bonuses stack, and your equipped look is shown in your room.') }<div class="wardrobe-head">${categories.map(c=>`<button class="${cat===c?'active':''}" onclick="activeCategory='${c}';render()">${c.toUpperCase()}</button>`).join('')}</div><div class="item-grid">${catalog[cat].map((it,i)=>{let owned=(state.owned[cat]||[]).includes(it[0]),equipped=state.wardrobe[cat]===it[0];return `<div class="closet-item ${equipped?'equipped':''}"><div><strong>${it[0]} ${equipped?'✓':''}</strong><small>${it[2]} · ${it[1]} clean ₡</small></div>${owned?`<button class="action-btn" onclick="equip('${cat}','${it[0]}')">${equipped?'EQUIPPED':'EQUIP'}</button>`:`<button class="action-btn" onclick="buyClothing('${cat}',${i})">BUY</button>`}</div>`}).join('')}</div><div class="card" style="margin-top:12px"><h4>Equipped bonuses</h4><div class="status-row"><span>Base stats</span><b>GRIT ${state.stats.grit} · CPU ${state.stats.cpu} · FOCUS ${state.stats.focus}</b></div><div class="status-row"><span>With clothing</span><b>${Object.entries(totalStats()).map(([k,v])=>`${k.toUpperCase()} ${v}`).join(' · ')}</b></div><p style="margin:8px 0 0">Starter pieces are free. Higher tiers cost more, but job income scales to match.</p></div></div>`}
function equip(cat,name){state.wardrobe[cat]=name;save();render();showToast(`${name} equipped. Bonus stats updated.`)}
function buyClothing(cat,i){let it=catalog[cat][i];if(state.clean<it[1])return showToast('Not enough clean money. Launder or earn more clean pay.');state.clean-=it[1];state.owned[cat].push(it[0]);state.wardrobe[cat]=it[0];save();render();showToast(`${it[0]} added to your wardrobe.`)}
const props=[['🪴','Holo fern',55,'+1 Focus','focus',1],['🖥️','Cracked terminal',80,'+1 CPU','cpu',1],['🛋️','Modular couch',130,'+2 Focus','focus',2],['🔊','Bass amp',150,'+2 Grit','grit',2],['🗼','Signal beacon',260,'+2 CPU','cpu',2],['🧬','Neural shrine',400,'+3 Focus','focus',3]];
function roomStats(){let s={...totalStats()};for(let name of state.roomProps){let p=props.find(x=>x[1]===name);if(p)s[p[4]]+=p[5]}return s}
function renderRoom(){let ps=state.roomProps.map((name,i)=>props.find(x=>x[1]===name)).filter(Boolean);let stats=roomStats();return `${panelHead('room',`${esc(state.name)}’s room`,'A small home above the city. Furnish it for comfort and permanent stat bonuses.') }<div class="room-scene"><div class="room-title">UNIT 09-${String(state.level).padStart(2,'0')} · ${esc(state.name.toUpperCase())}</div><span class="prop left">${ps[0]?.[0]||'🪴'}</span><div class="room-person"></div><span class="prop right">${ps[1]?.[0]||'🖥️'}</span><div class="room-floor"></div><div class="room-footer">${state.clan?`CLAN ${esc(state.clan)}`:'OPEN DOOR · VISITORS WELCOME'}</div></div><div class="two-col"><div class="card"><h4>Public room perks</h4>${Object.entries(stats).map(([k,v])=>`<div class="status-row"><span>${k.toUpperCase()} TOTAL</span><b>${v}</b></div>`).join('')}<p>Clothing and furniture bonuses stack for jobs.</p></div><div class="card"><h4>Available furniture</h4><div class="shop-list">${props.map((p,i)=>{let has=state.roomProps.includes(p[1]);return `<div class="shop-item"><div><strong>${p[0]} ${p[1]}</strong><small>${p[3]} · ${p[2]} clean ₡</small></div><button class="action-btn" ${has?'disabled':''} onclick="buyProp(${i})">${has?'OWNED':'ADD'}</button></div>`}).join('')}</div></div></div></div>`}
function buyProp(i){let p=props[i];if(state.clean<p[2])return showToast('Not enough clean money for this furniture.');if(state.roomProps.includes(p[1]))return showToast('Already in your room.');state.clean-=p[2];state.roomProps.push(p[1]);save();render();showToast(`${p[1]} installed. Your room bonus increased.`)}
function renderClans(){return `${panelHead('clans','Find your people','Make a clan or join an open crew. Your origin faction is separate from player clans.') }<div class="two-col"><div class="card"><h4>Create a clan</h4><p>Start a crew with a name and a clear signal. Creating costs ₡100 clean.</p><form id="clanForm"><div class="form-row"><input id="clanName" maxlength="20" placeholder="Clan name"><button class="action-btn">CREATE · ₡100</button></div></form></div><div class="card"><h4>Your affiliation</h4><div class="status-row"><span>Origin faction</span><b>${esc(state.faction||'Independent')}</b></div><div class="status-row"><span>Player clan</span><b>${esc(state.clan||'None yet')}</b></div><p>Clan memberships are social. No stat penalty for switching.</p></div></div><h4 style="font-size:11px;margin:15px 0 8px">OPEN CLANS</h4><div class="clan-list">${state.clans.map((c,i)=>`<div class="clan"><div><strong>✳ ${esc(c.name)} <span class="tag">${esc(c.tag)}</span></strong><small>LEVEL ${c.level} · ${c.members} MEMBERS<br>${esc(c.about)}</small></div><button class="action-btn" onclick="joinClan(${i})">${state.clan===c.name?'MEMBER':'JOIN'}</button></div>`).join('')}</div></div>`}
function joinClan(i){state.clan=state.clans[i].name;state.clans[i].members++;save();render();showToast(`Welcome to ${state.clan}.`)}
function renderBank(){let amount=Number($('#launderAmount')?.value)||50;return `${panelHead('bank','Your accounts','Dirty cash from risky work must be laundered before it can enter your bank. A 15% service fee applies.') }<div class="economy-grid"><div class="money dirty"><small>ON HAND · DIRTY CASH</small><strong>₡ ${state.dirty}</strong><small>Job proceeds · cannot deposit directly</small></div><div class="money clean"><small>ON HAND · CLEAN MONEY</small><strong>₡ ${state.clean}</strong><small>Spendable wardrobe & room funds</small></div><div class="money"><small>PERSONAL BANK</small><strong>₡ ${state.bank}</strong><small>Secure clean savings</small></div><div class="money"><small>POCKET CASH</small><strong>₡ ${state.cash}</strong><small>Everyday job payout</small></div></div><div class="two-col"><div class="card"><h4>Night market laundromat</h4><p>Choose an amount of dirty cash. The cycle takes 10 seconds in this demo, with a 15% fee. Launder up to ₡300 per cycle.</p><div class="form-row"><input id="launderAmount" type="number" min="10" max="300" step="10" value="50"><button class="action-btn" onclick="startLaunder()">START CYCLE</button></div><div id="launderStatus" class="form-note">${state.launderUntil>Date.now()?`CYCLE RUNNING · ${Math.ceil((state.launderUntil-Date.now())/1000)}s remaining`:'Cycles complete instantly in prototype mode after 10 seconds.'}</div><p>Clean payout after fee: <b style="color:var(--green)">₡ ${Math.floor(amount*.85)}</b></p></div><div class="card"><h4>Bank transfer</h4><p>Move clean money to protected savings. Withdraw any time.</p><div class="form-row"><input id="bankAmount" type="number" min="1" value="50"><button class="action-btn" onclick="transferBank('deposit')">DEPOSIT</button><button class="action-btn" onclick="transferBank('withdraw')">WITHDRAW</button></div><div class="status-row"><span>Current bank balance</span><b>₡ ${state.bank}</b></div><p>Jobs pay mostly in dirty cash, with smaller clean bonuses. The laundering loop is your bridge to premium gear.</p></div></div></div>`}
function startLaunder(){let amount=Math.floor(Number($('#launderAmount').value));if(state.launderUntil>Date.now())return showToast('A laundering cycle is already running.');if(!amount||amount<10||amount>300||amount>state.dirty)return showToast('Enter an amount from ₡10 to ₡300 within your dirty balance.');state.dirty-=amount;state.launderAmount=amount;state.launderUntil=Date.now()+10000;save();render();showToast('Cycle started. Come back in 10 seconds.');setTimeout(()=>{if(state.launderUntil&&Date.now()>=state.launderUntil){state.clean+=Math.floor(state.launderAmount*.85);state.launderUntil=0;save();if(state.activeView==='bank')render();showToast('Laundering complete. Clean funds are ready.')}},10100)}
function transferBank(mode){let amount=Math.floor(Number($('#bankAmount').value));if(!amount||amount<1)return showToast('Enter a valid amount.');if(mode==='deposit'){if(amount>state.clean)return showToast('Not enough clean money.');state.clean-=amount;state.bank+=amount}else{if(amount>state.bank)return showToast('Not enough in your bank.');state.bank-=amount;state.clean+=amount}save();render();showToast(mode==='deposit'?'Clean money deposited.':'Bank withdrawal complete.')}

