 function renderJobs(){let s=roomStats();$('#content').innerHTML=`<div class="two"><div class="panel"><h3>Available contracts</h3>${jobs.map((j,i)=>`<div class="job"><h4>${j[0]} <span class="tag">${j[1].toUpperCase()}</span></h4><p>${j[2]} · Requires ${j[3]} · ${j[4].toUpperCase()} cost ${j[5]}</p><div class="jobbar"><small>${j[7]} dirty / ${j[9]} clean ₡</small><button class="smallbtn" onclick="doJob(${i})">RUN</button></div></div>`).join('')}</div><div class="panel"><h3>Character energy</h3><div class="row"><span>ACTION</span><b>${state.action}/100</b></div><div class="row"><span>CPU</span><b>${state.cpu}/100</b></div><div class="row"><span>FOCUS</span><b>${state.focus}/100</b></div><h3 style="margin-top:16px">Stats with gear & room</h3><div class="row"><span>GRIT</span><b>${s.grit}</b></div><div class="row"><span>CPU</span><b>${s.cpu}</b></div><div class="row"><span>FOCUS</span><b>${s.focus}</b></div></div></div>`}function doJob(i){let j=jobs[i],s=roomStats(),map={Grit:s.grit,CPU:s.cpu,Focus:s.focus};let req=j[3];let ok=true;if(j[1]=='Easy'&&s.grit<3)ok=false;if(j[1]=='Medium'&&s.cpu<5)ok=false;if(j[1]=='Hard'&&s.focus<6)ok=false;if(j[1]=='Legendary'&&(s.grit<8||s.cpu<8))ok=false;if(!ok)return showToast('You need stronger gear or furniture for this contract.');let cost=j[5],key=j[4];if(state[key]<cost)return showToast(`Not enough ${key.toUpperCase()} energy. Rest to refill.`);state[key]-=cost;state.dirty+=j[7];state.clean+=j[9];state.xp+=parseInt(j[2]);if(state.xp>=state.level*100){state.level++;state.xp=0;state.stats={grit:state.stats.grit+1,cpu:state.stats.cpu+1,focus:state.stats.focus+1}}save();renderView('jobs');showToast(`Contract complete. Earned ${j[7]} dirty and ${j[9]} clean ₡.`)}
 function renderWardrobe(){let cat=window.activeCat||'Shoes';$('#content').innerHTML=`<div class="choices">${Object.keys(catalog).map(c=>`<button class="choice ${cat==c?'on':''}" onclick="activeCat='${c}';renderView('wardrobe')">${c.toUpperCase()}</button>`).join('')}</div><div class="catalog" style="margin-top:10px">${catalog[cat].map((it,i)=>{let owned=state.owned[cat].includes(it[0]),eq=state.wardrobe[cat]==it[0];return `<div class="item ${eq?'on':''}"><h4>${it[0]} ${eq?'✓':''}</h4><small>${it[2]} · ${owned?'OWNED':it[1]+' clean ₡'}</small><br><button class="smallbtn" style="margin-top:8px" onclick="${owned?`equipItem('${cat}','${it[0]}')`:`buyItem('${cat}',${i})`}" ${eq?'disabled':''}>${eq?'EQUIPPED':owned?'EQUIP':'BUY'}</button></div>`}).join('')}</div><div class="panel" style="margin-top:10px"><h3>Equipped total stats</h3><div class="row"><span>GRIT · CPU · FOCUS</span><b>${totalStats().grit} · ${totalStats().cpu} · ${totalStats().focus}</b></div></div>`}function buyItem(cat,i){let it=catalog[cat][i];if(state.clean<it[1])return showToast('Not enough clean money. Launder dirty cash first.');state.clean-=it[1];state.owned[cat].push(it[0]);state.wardrobe[cat]=it[0];save();renderView('wardrobe');showToast(`${it[0]} equipped.`)}function equipItem(cat,name){state.wardrobe[cat]=name;save();renderView('wardrobe')}
